/** One glyph: `size` is the font size, so the 512-unit em fills a `size` square. */
@Composable
internal fun MdiIcon(path: String, size: Float, color: Color, modifier: Modifier = Modifier) {
    val parsed = remember(path) { PathParser().parsePathString(path).toPath() }
    Canvas(modifier.size(size.dp)) {
        val s = this.size.width / 512f
        val scaled = Path().apply { addPath(parsed); transform(androidx.compose.ui.graphics.Matrix().apply { scale(s, s) }) }
        drawPath(scaled, color)
    }
}
